export declare const CSS = "/*\n  GIKOU Media Design Token \u2014 \u6B63\u672C\uFF082026-10-05\uFF09\n  \u898B\u3066\u6C7A\u3081\u308B\u677F\u306F design/index.html\u3002Astro\uFF08\u5B9F\u88C5\u8A08\u753B \u6BB5 2b\uFF09\u306F\u3053\u306E\u30D5\u30A1\u30A4\u30EB\u3092\u8AAD\u3080\u3002\n  3 \u5206\u985E\u306F\u300C\u8AB0\u306E\u8A00\u8449\u304B\u300D\u3092\u300C\u8AB0\u306E\u8272\u304B\u300D\u3067\u793A\u3059\u3002\u6587\u5B57\u306F\u5E38\u306B\u9ED2\uFF08\u8272\u6587\u5B57\u3092\u4F7F\u308F\u306A\u3044\uFF09\u3002\n  \u30E2\u30CE\u30AF\u30ED\u5370\u5237\u304C\u524D\u63D0\uFF1A3 \u8272\u306F\u7070\u8272\u306B\u3057\u305F\u3068\u304D\u6FC3\u3055\u304C 3 \u6BB5\uFF08\u6FC3\u30FB\u4E2D\u30FB\u6DE1\uFF09\u306B\u5206\u304B\u308C\u308B\u5024\u3092\u9078\u3076\u3002\n  \u5730\u8272\u306F\u5370\u5237\u3067\u843D\u3061\u3066\u3088\u3044\u3002\u898B\u5206\u3051\u306F\u5E2F\u306E\u6FC3\u3055\u30FB\u30A2\u30A4\u30B3\u30F3\u30FB\u30E9\u30D9\u30EB\u3067\u62C5\u4FDD\u3059\u308B\u3002\n*/\n:root {\n  /* \u516C\u5F0F = Cloudflare \u306E\u30ED\u30B4\u306E 2 \u8272\uFF08\u7070\u8272\u306B\u3059\u308B\u3068\u4E2D \u2248 151\uFF09 */\n  --source-official-fg: #f38020;\n  --source-official-light: #faae40;\n  --source-official-bg: #fef3e4;\n\n  /* \u975E\u516C\u5F0F = \u6DE1\u3044\u7DD1\uFF08\u3069\u306E\u767A\u4FE1\u8005\u306E\u8272\u3067\u3082\u306A\u3044\u3002\u7070\u8272\u306B\u3059\u308B\u3068\u6DE1 \u2248 196\uFF09 */\n  --source-unofficial-fg: #9ed9be;\n  --source-unofficial-light: #cdeedd;\n  --source-unofficial-bg: #eef8f3;\n\n  /* GIKOU Media = GIKOU \u306E\u9752\uFF08\u7070\u8272\u306B\u3059\u308B\u3068\u6FC3 \u2248 67\uFF09 */\n  --source-gikou-media-fg: #164a94;\n  --source-gikou-media-light: #7cb8f0;\n  --source-gikou-media-bg: #e8f1fc;\n\n  /* \u5730\u3068\u6587\u5B57 */\n  --ink: #1a1c1f;\n  --muted: #3a3f47; /* \u6CE8\u8A18\u30FB\u65E5\u4ED8\u3002\u5370\u5237\u3067\u304F\u3063\u304D\u308A\u51FA\u308B\u6FC3\u3055 */\n  --line: #d9dce1;\n  --paper: #ffffff;\n  --canvas: #f7f7f8;\n\n  /* \u30EA\u30F3\u30AF\uFF1AGIKOU \u306E\u9752\uFF0B\u4E0B\u7DDA\u3002GIKOU Media \u306E\u5E2F\u3068\u540C\u3058\u5024\u3060\u304C\u3001\u4E0B\u7DDA\u3067\u898B\u5206\u3051\u308B */\n  --link: var(--source-gikou-media-fg);\n\n  /* \u6708\u6B21\u30EC\u30DD\u30FC\u30C8\u306E Graph \u306F\u7121\u5F69\u8272\uFF083 \u5206\u985E\u306E\u8272\u3068\u6DF7\u305C\u306A\u3044\uFF09 */\n  --chart-1: #3a3f47;\n  --chart-2: #b8bdc5;\n\n  /* \u66F8\u4F53\uFF08\u4EEE\u7F6E\u304D\u30FB\u672A\u6C7A\uFF09 */\n  --font-sans: \"IBM Plex Sans JP\", \"Hiragino Sans\", \"Noto Sans JP\", sans-serif;\n  --font-mono: \"IBM Plex Mono\", ui-monospace, Menlo, monospace;\n\n  /* \u672C\u6587\u5E45\u30FB\u4F59\u767D\u30FB\u5927\u304D\u3055\uFF08GIKOU \u30C6\u30FC\u30DE\u306E\u6700\u5C0F\u30BB\u30C3\u30C8\uFF09 */\n  --measure: 40rem;\n  --space-1: 0.25rem;\n  --space-2: 0.5rem;\n  --space-3: 0.75rem;\n  --space-4: 1rem;\n  --space-6: 1.5rem;\n  --space-8: 2rem;\n  --text-xs: 0.6875rem;\n  --text-sm: 0.75rem;\n  --text-base: 0.875rem;\n  --text-lg: 1.125rem;\n  --text-xl: 1.25rem;\n  --text-2xl: 1.75rem;\n  --leading: 1.7;\n  --radius: 4px;\n}\n\n/* Primitive \u306F data-source-type \u3060\u3051\u898B\u3066\u8272\u3092\u5F53\u3066\u308B\uFF08R-UI-4\uFF09 */\n[data-source-type=\"official\"] {\n  --sfg: var(--source-official-fg);\n  --slight: var(--source-official-light);\n  --sbg: var(--source-official-bg);\n}\n[data-source-type=\"unofficial\"] {\n  --sfg: var(--source-unofficial-fg);\n  --slight: var(--source-unofficial-light);\n  --sbg: var(--source-unofficial-bg);\n}\n[data-source-type=\"gikou_media\"] {\n  --sfg: var(--source-gikou-media-fg);\n  --slight: var(--source-gikou-media-light);\n  --sbg: var(--source-gikou-media-bg);\n}\n/* docgen \u306E\u6587\u66F8\uFF08\u6708\u6B21\u30EC\u30DD\u30FC\u30C8\uFF09\u3002\u677F design/index.html \u306E\u300C06 \u6708\u6B21\u30EC\u30DD\u30FC\u30C8\u300D\u304B\u3089\u79FB\u3057\u305F\u3002\u8272\u30FB\u66F8\u4F53\u306F tokens.css \u306E\u5909\u6570\u3060\u3051 */\nbody {\n  margin: 0;\n  background: var(--canvas);\n  color: var(--ink);\n  font-family: var(--font-sans);\n  font-size: var(--text-base);\n  line-height: var(--leading);\n}\na {\n  color: var(--link);\n  text-decoration: underline;\n  text-underline-offset: 2px;\n}\ncode,\n.mono {\n  font-family: var(--font-mono);\n  font-size: var(--text-xs);\n}\n.sheet {\n  background: var(--paper);\n  width: 794px;\n  box-sizing: border-box;\n  padding: 56px 56px 40px;\n  margin: 24px auto;\n}\n.doc-header .kicker {\n  font-family: var(--font-mono);\n  font-size: var(--text-xs);\n  letter-spacing: 0.12em;\n  color: var(--muted);\n}\n.doc-header h1 {\n  font-size: var(--text-2xl);\n  letter-spacing: -0.01em;\n  margin: var(--space-2) 0 var(--space-3);\n}\n.doc-header hr {\n  border: 0;\n  border-top: 1px solid var(--ink);\n  margin: 0;\n}\n.doc-header .month {\n  font-size: 16px;\n  font-weight: 500;\n  margin: var(--space-3) 0;\n}\n.doc-header dl {\n  display: grid;\n  grid-template-columns: 120px 1fr;\n  gap: 4px 0;\n  margin: 0 0 var(--space-3);\n  font-family: var(--font-mono);\n  font-size: var(--text-xs);\n}\n.doc-header dt {\n  color: var(--muted);\n}\n.doc-header dd {\n  margin: 0;\n  font-weight: 500;\n}\n.section {\n  margin-top: 36px;\n}\n.section h2 {\n  font-size: var(--text-xl);\n  margin: 0 0 var(--space-3);\n}\n.section h2 small {\n  font-family: var(--font-mono);\n  font-size: 13px;\n  font-weight: 400;\n  color: var(--muted);\n  margin-right: 12px;\n}\n.section p {\n  margin: var(--space-2) 0;\n}\n.empty {\n  color: var(--muted);\n  font-size: var(--text-sm);\n  border: 1px dashed var(--line);\n  border-radius: 6px;\n  padding: 10px 14px;\n}\n.metrics {\n  display: grid;\n  /* \u9805\u76EE\u540D\u304C\u9577\u304F\u3066\u3082\u5217\u3092\u62BC\u3057\u5E83\u3052\u306A\u3044\uFF08health.duplicate_claims_retrieval \u306A\u3069\uFF09 */\n  grid-template-columns: repeat(4, minmax(0, 1fr));\n  gap: 12px;\n  margin-top: 16px;\n}\n.metric {\n  background: var(--canvas);\n  border-radius: 6px;\n  padding: 12px 14px;\n  display: grid;\n  gap: 4px;\n}\n.metric .label {\n  font-size: var(--text-xs);\n  color: var(--muted);\n}\n.metric .value {\n  font-size: 26px;\n  font-weight: 600;\n  letter-spacing: -0.02em;\n  line-height: 1.2;\n}\n.metric .value small {\n  font-size: var(--text-sm);\n  font-weight: 400;\n  margin-left: 4px;\n}\n.metric[data-measured=\"false\"] .value {\n  font-size: 16px;\n  color: var(--muted);\n}\n.metric .delta {\n  font-size: var(--text-xs);\n  font-weight: 500;\n}\n.metric .ref {\n  font-family: var(--font-mono);\n  font-size: 10px;\n  color: var(--muted);\n  overflow-wrap: anywhere;\n}\n.chart {\n  border: 1px solid var(--line);\n  border-radius: 6px;\n  padding: 14px 16px;\n  margin: 24px 0 0;\n}\n.chart .title {\n  font-size: 13px;\n  font-weight: 500;\n  margin: 0 0 var(--space-2);\n}\n.chart .title small {\n  font-family: var(--font-mono);\n  font-size: var(--text-xs);\n  font-weight: 400;\n  color: var(--muted);\n  margin-right: var(--space-2);\n}\n.chart svg {\n  width: 100%;\n  height: auto;\n  display: block;\n  font-family: var(--font-mono);\n  font-size: 11px;\n  fill: var(--ink);\n}\n.chart .caption {\n  font-size: var(--text-xs);\n  color: var(--muted);\n  border-top: 1px solid var(--line);\n  padding-top: var(--space-2);\n  margin: var(--space-2) 0 0;\n}\ntable.data {\n  border: 1px solid var(--line);\n  border-collapse: separate;\n  border-spacing: 0;\n  width: 100%;\n  font-size: var(--text-sm);\n  border-radius: 6px;\n  margin-top: 16px;\n}\ntable.data th {\n  background: var(--canvas);\n  text-align: left;\n  font-weight: 500;\n  font-size: var(--text-xs);\n  color: var(--muted);\n  padding: 8px 12px;\n}\ntable.data td {\n  padding: 8px 12px;\n  border-top: 1px solid var(--line);\n  vertical-align: top;\n}\n.finding {\n  border-left: 3px solid var(--ink);\n  background: var(--canvas);\n  padding: 10px 14px;\n  margin: 12px 0;\n  border-radius: 3px;\n}\n.finding-refs {\n  font-size: var(--text-xs);\n  color: var(--muted);\n  margin-bottom: 4px;\n}\n.finding p,\n.action p {\n  margin: 0;\n}\n.action {\n  display: flex;\n  gap: 8px;\n  align-items: baseline;\n  margin: 8px 0;\n}\n.chip {\n  display: inline-block;\n  border: 1px solid var(--line);\n  border-radius: 3px;\n  padding: 1px 6px;\n  font-size: var(--text-xs);\n  color: var(--ink);\n  flex: none;\n}\n.doc-footer {\n  margin-top: 40px;\n  border-top: 1px solid var(--line);\n  padding-top: 12px;\n  display: grid;\n  gap: 6px;\n  font-size: var(--text-xs);\n  color: var(--muted);\n}\n.doc-footer p {\n  margin: 0;\n}\n\n/* Print\uFF1AA4\u30FB\u90E8\u54C1\u5358\u4F4D\u3067\u6539\u30DA\u30FC\u30B8\u3092\u907F\u3051\u308B\u30FB\u898B\u51FA\u3057\u306E\u5E2F\u3068\u30DA\u30FC\u30B8\u756A\u53F7\u3092\u5404\u30DA\u30FC\u30B8\u306B\u30FB\u30EA\u30F3\u30AF\u5148\u3092\u8868\u793A\u30FB\u5730\u8272\u306F\u6B8B\u3055\u306A\u3044\uFF08\u30E2\u30CE\u30AF\u30ED\u524D\u63D0\u30FBR-UI-7\uFF09\u3002\n   Footer \u306F\u6700\u7D42\u30DA\u30FC\u30B8\u3060\u3051\uFF08\u5404\u30DA\u30FC\u30B8\u306B\u7E70\u308A\u8FD4\u3059 string-set \u306F Chrome \u304C\u5BFE\u5FDC\u3057\u306A\u3044\u30FB2026-10-06\uFF09 */\n@page {\n  size: A4;\n  margin: 18mm 16mm 20mm;\n  @top-left {\n    content: \"GIKOU MEDIA \u00B7 MONTHLY OBSERVATION \u00B7 \" var(--month, \"\");\n    font-family: var(--font-mono);\n    font-size: 8pt;\n    color: #3a3f47;\n  }\n  @bottom-right {\n    content: counter(page) \" / \" counter(pages);\n    font-family: var(--font-mono);\n    font-size: 8pt;\n    color: #3a3f47;\n  }\n}\n@media print {\n  body {\n    background: none;\n  }\n  .sheet {\n    width: auto;\n    margin: 0;\n    padding: 0;\n  }\n  .metric,\n  .finding {\n    background: none;\n    border: 1px solid var(--line);\n  }\n  .chart,\n  .metrics,\n  table.data,\n  .finding,\n  .action,\n  .doc-header {\n    break-inside: avoid;\n  }\n  .section h2 {\n    break-after: avoid;\n  }\n  a[href^=\"http\"]::after {\n    content: \" (\" attr(href) \")\";\n    font-family: var(--font-mono);\n    font-size: 7pt;\n  }\n}\n";
